  // client/src/ui/model.ts
  "Leaving": "Đang rời đi",
  "Working…": "Đang làm việc…",
  "Needs you: {0}": "Cần bạn: {0}",
  "Waiting for the shell to finish": "Đang chờ shell kết thúc",
  "Finished the task": "Đã hoàn thành tác vụ",
  "Leaving the office": "Đang rời văn phòng",
  "Waiting for instructions": "Đang chờ chỉ dẫn",
  "background": "chạy nền",
  "foreground": "chạy trực tiếp",
  "Waiting for the command to finish": "Đang chờ lệnh kết thúc",
  "Stuck on a terminal command, waiting for it to finish to continue the turn.": "Đang kẹt ở một lệnh trong terminal, chờ nó kết thúc để tiếp tục lượt.",
  "Finished the turn and is waiting for {0} shells to finish. As each one finishes, the agent gets its result.": "Đã xong lượt và đang chờ {0} shell kết thúc. Mỗi khi một shell kết thúc, agent nhận được kết quả.",
  "Finished the turn and is waiting for the shell to finish. When it does, the agent gets the result.": "Đã xong lượt và đang chờ shell kết thúc. Khi nó kết thúc, agent nhận được kết quả.",
  "Eating popcorn and watching the terminal": "Ăn bắp rang và xem terminal",
  "Up to 3 min: leans back in the chair with a bucket of popcorn and watches the terminal like a movie.": "Đến 3 phút: ngả lưng trên ghế với xô bắp rang và xem terminal như xem phim.",
  "Out of popcorn: spinning in the chair": "Hết bắp rang: xoay ghế vòng vòng",
  "From 3 to 10 min: the popcorn runs out; arms crossed, fingers tapping and, now and then, a full spin in the chair.": "Từ 3 đến 10 phút: bắp rang hết; khoanh tay, gõ ngón tay và thỉnh thoảng xoay trọn một vòng trên ghế.",
  "There's a cobweb on the chair already": "Ghế đã có mạng nhện",
  "After 10 min: a cobweb appears on the chair (it grows after 20 min) and a yawn slips out.": "Sau 10 phút: một mạng nhện xuất hiện trên ghế (to ra sau 20 phút) và một cái ngáp thoát ra.",
  "Dozed off waiting on the shell": "Ngủ gật khi chờ shell",
  "After 25 min: naps at the desk, covered in cobwebs.": "Sau 25 phút: ngủ gật ở bàn, phủ đầy mạng nhện.",
  "shortcut {0}": "phím tắt {0}",
  "shortcuts {0} or {1}": "phím tắt {0} hoặc {1}",

  // client/src/ui/movable.ts
  "Restore size": "Khôi phục kích thước",
