  // scripts/codex-install.ts
  "Waiting for an answer in Habblaud…": "Đang chờ câu trả lời trong Habblaud…",
  "Usage: npm run codex:<install|uninstall|status> [-- options]\n\n  install     adds the Habblaud hooks to the hooks.json in each Codex folder (backs it up first)\n  uninstall   removes the Habblaud hooks from each folder (other hooks stay)\n  status      shows whether the hooks are there and whether Habblaud is responding\n\nOptions:\n  --dry-run        shows what would change, without writing anything\n  --conta <id>     only this account's folder (the folder name, e.g. .codex)\n  --port <n>       Habblaud port (default: HABBLAUD_PORT or {0})\n  --espera <s>     how long Codex waits for your answer in Habblaud before asking for approval in the terminal\n                   (default: {1} s; between {2} and {3})\n  --node <path>    the Node {4}+ that runs the hooks (default: the login shell's `node`, if it is {5}+;\n                   otherwise the first {6}+ among /opt/homebrew/bin, /usr/local/bin and the one running this command)\n  -h, --help       shows this help\n\nFolders: HABBLAUD_CODEX_DIRS (comma-separated list) or CODEX_HOME and Codex's ~/.codex* folders.\nAfter installing, open Codex and approve the Habblaud hooks in /hooks.": "Cách dùng: npm run codex:<install|uninstall|status> [-- tùy chọn]\n\n  install     thêm các hook của Habblaud vào hooks.json của từng thư mục Codex (sao lưu trước)\n  uninstall   gỡ các hook của Habblaud khỏi từng thư mục (các hook khác được giữ nguyên)\n  status      cho biết các hook đã có chưa và Habblaud có đang phản hồi không\n\nTùy chọn:\n  --dry-run        cho biết sẽ thay đổi gì, không ghi gì cả\n  --conta <id>     chỉ thư mục của tài khoản này (tên thư mục, ví dụ: .codex)\n  --port <n>       cổng của Habblaud (mặc định: HABBLAUD_PORT hoặc {0})\n  --espera <s>     Codex chờ câu trả lời của bạn trong Habblaud bao lâu trước khi xin phê duyệt ở terminal\n                   (mặc định: {1} giây; từ {2} đến {3})\n  --node <đường dẫn> Node {4}+ chạy các hook (mặc định: `node` của login shell, nếu là {5}+;\n                   nếu không thì {6}+ đầu tiên trong /opt/homebrew/bin, /usr/local/bin và Node của lệnh này)\n  -h, --help       hiện trợ giúp này\n\nThư mục: HABBLAUD_CODEX_DIRS (danh sách cách nhau bằng dấu phẩy) hoặc CODEX_HOME và các thư mục ~/.codex* của Codex.\nSau khi cài, hãy mở Codex và phê duyệt các hook của Habblaud trong /hooks.",
  "\"hooks\" in an unknown format; nothing was changed": "\"hooks\" có định dạng không xác định; không có gì bị thay đổi",
  "\"hooks.{0}\" in an unknown format; nothing was changed": "\"hooks.{0}\" có định dạng không xác định; không có gì bị thay đổi",
  "already installed": "đã cài đặt",
  "installed in {0}": "đã cài đặt trong {0}",
  "installed ({0} events)": "đã cài đặt ({0} sự kiện)",
  "updated in {0}": "đã cập nhật trong {0}",
  "wasn't installed": "chưa được cài đặt",
  "Habblaud hooks removed": "đã gỡ các hook của Habblaud",
  "--conta needs the account folder name (e.g. .codex).": "--conta cần tên thư mục của tài khoản (ví dụ: .codex).",
  "--espera needs a number of seconds between {0} and {1}.": "--espera cần một số giây từ {0} đến {1}.",
  "--node needs the absolute path to a Node 22+ (e.g. /opt/homebrew/bin/node).": "--node cần đường dẫn tuyệt đối đến Node 22+ (ví dụ: /opt/homebrew/bin/node).",
