  "! old name still registered: {0}; npm run mod:install replaces it with habblaud": "! tên cũ vẫn còn được đăng ký: {0}; npm run mod:install sẽ đổi sang habblaud",
  "! old statusline tap still installed alongside the mod: npm run mod:install removes it (or npm run usage:uninstall)": "! tap statusline cũ vẫn còn được cài cùng với mod: npm run mod:install sẽ gỡ nó (hoặc npm run usage:uninstall)",
