  "! old permission hook still in settings.json alongside the plugin: both answer; npm run mod:install removes it (or npm run hooks:uninstall)": "! hook cấp quyền cũ vẫn còn trong settings.json cùng với plugin: cả hai đều trả lời; npm run mod:install sẽ gỡ nó (hoặc npm run hooks:uninstall)",
  "old permission hook installed (old way; the permissions plugin replaces it)": "đã cài hook cấp quyền cũ (cách cũ; plugin cấp quyền sẽ thay thế nó)",
  "! disableAllHooks is on in this account's settings.json: no mod (or hook) runs": "! disableAllHooks đang bật trong settings.json của tài khoản này: không có mod (hay hook) nào chạy",
  "--conta needs the account folder (e.g. --conta ~/.claude-conta2).": "--conta cần thư mục của tài khoản (ví dụ: --conta ~/.claude-conta2).",
