  "couldn't parse Claude Code's plugin list": "không hiểu danh sách plugin của Claude Code",
  "--conta {0}: folder not found.": "--conta {0}: không tìm thấy thư mục.",
  "last usage captured {0} ago ({1})": "lần dùng gần nhất được ghi nhận cách đây {0} ({1})",
