  "Delivering Habblaud messages (http://127.0.0.1:{0}) to Codex sessions with {1}, and starting the new agents requested in the office. Ctrl+C to stop.": "Đang chuyển tin nhắn của Habblaud (http://127.0.0.1:{0}) đến các phiên Codex bằng {1}, và bắt đầu các agent mới được yêu cầu trong văn phòng. Nhấn Ctrl+C để dừng.",
  "No Codex (codex in PATH or HABBLAUD_CODEX_BIN): only starting the new agents requested in Habblaud (http://127.0.0.1:{0}). Ctrl+C to stop.": "Không có Codex (codex trong PATH hoặc HABBLAUD_CODEX_BIN): chỉ bắt đầu các agent mới được yêu cầu trong Habblaud (http://127.0.0.1:{0}). Nhấn Ctrl+C để dừng.",
  "New agents run in the background with {0} --bg (trusted folder; otherwise, in the Claude app).": "Agent mới chạy nền bằng {0} --bg (thư mục đã tin cậy; nếu không thì mở trong ứng dụng Claude).",
  "No claude in PATH (or HABBLAUD_CLAUDE_BIN): new agents open in the Claude app and wait for Enter.": "Không có claude trong PATH (hoặc HABBLAUD_CLAUDE_BIN): agent mới mở trong ứng dụng Claude và chờ nhấn Enter.",
  "Dictation off: {0} is missing.": "Đọc chính tả đã tắt: thiếu {0}.",
