  // scripts/remote-mdns.ts
  "[remote-mdns] no valid HABBLAUD_REMOTE_NAME in .env: run npm run remote:setup.": "[remote-mdns] không có HABBLAUD_REMOTE_NAME hợp lệ trong .env: hãy chạy npm run remote:setup.",
  "[remote-mdns] no network: announcement paused.": "[remote-mdns] không có mạng: tạm dừng thông báo.",
  "[remote-mdns] {0} not supported: use the IP or an address in the router's DNS.": "[remote-mdns] {0} không được hỗ trợ: hãy dùng IP hoặc một địa chỉ trong DNS của router.",
  "[remote-mdns] couldn't run {0}: {1}": "[remote-mdns] không chạy được {0}: {1}",
  "[remote-mdns] announcing {0}.local -> {1}": "[remote-mdns] đang thông báo {0}.local -> {1}",

  // scripts/remote-setup.ts
  "Usage: npm run remote:setup [-- options]\n\nTurns on phone access (https://<name>.local) with username, password and HTTPS.\n\n  --user <name>        login username (default: your system username)\n  --name <name>        address <name>.local (default: habblaud)\n  --domain <address>   own address, e.g. myclaude.home (needs an entry in the router's DNS)\n  --port <n>           port on the computer (default: 443 if free, otherwise 4748)\n  --allow <list>       what the phone can do: permissions, messages, terminal, spawn, none (default: permissions)\n  --password-stdin     reads the password from standard input (automation) instead of asking\n  --no-service         doesn't install the <name>.local announcement service (run npm run remote:mdns yourself)\n  --off                turns off phone access (removes the lines from .env and the service; keeps the CA)": "Cách dùng: npm run remote:setup [-- tùy chọn]\n\nBật truy cập bằng điện thoại (https://<tên>.local) với tên người dùng, mật khẩu và HTTPS.\n\n  --user <tên>         tên đăng nhập (mặc định: tên người dùng hệ thống của bạn)\n  --name <tên>         địa chỉ <tên>.local (mặc định: habblaud)\n  --domain <địa chỉ>   địa chỉ riêng, ví dụ: meuclaude.home (cần một mục trong DNS của router)\n  --port <n>           cổng trên máy tính (mặc định: 443 nếu còn trống, nếu không thì 4748)\n  --allow <danh sách>  điện thoại được làm gì: permissions, messages, terminal, spawn, none (mặc định: permissions)\n  --password-stdin     đọc mật khẩu từ đầu vào chuẩn (tự động hóa) thay vì hỏi\n  --no-service         không cài dịch vụ thông báo <tên>.local (tự chạy npm run remote:mdns)\n  --off                tắt truy cập bằng điện thoại (xóa các dòng trong .env và dịch vụ; giữ lại CA)",
  "missing value for {0}": "thiếu giá trị cho {0}",
  "unknown option: {0}": "tùy chọn không xác định: {0}",
  "invalid port": "cổng không hợp lệ",
  "use at least {0} characters": "dùng ít nhất {0} ký tự",
