  "the password can't be the username": "mật khẩu không được trùng với tên người dùng",
  "no terminal to ask for the password: use --password-stdin": "không có terminal để hỏi mật khẩu: hãy dùng --password-stdin",
  "service {0} enabled (log: ~/.habblaud/logs/remote-mdns.log)": "đã bật dịch vụ {0} (log: ~/.habblaud/logs/remote-mdns.log)",
  "couldn't enable the service: {0}": "không bật được dịch vụ: {0}",
  "Habblaud: announces the .local address for phone access": "Habblaud: thông báo địa chỉ .local của truy cập bằng điện thoại",
  "habblaud-remote-mdns service enabled (to keep it on while logged out: loginctl enable-linger)": "đã bật dịch vụ habblaud-remote-mdns (để tiếp tục chạy khi chưa đăng nhập: loginctl enable-linger)",
  "{0}: no automatic service; keep npm run remote:mdns running or use the IP": "{0}: không có dịch vụ tự động; hãy để npm run remote:mdns chạy hoặc dùng IP",
