  // client/src/ui/world/world-popups.ts
  "New: Habblaud World": "Có gì mới: Habblaud World",
  "Your office can now become a building in an online city, lit up while your agents work.": "Văn phòng của bạn giờ có thể trở thành một tòa nhà trong thành phố trực tuyến, sáng đèn khi các agent của bạn làm việc.",
  "Your office becomes a building in a pixel-art city, lit up while your agents work.": "Văn phòng của bạn trở thành một tòa nhà trong thành phố pixel art, sáng đèn khi các agent của bạn làm việc.",
  "Create a character, walk around the city and visit other people's buildings.": "Hãy tạo một nhân vật, đi dạo quanh thành phố và ghé thăm các tòa nhà của người khác.",
  "Greet passersby and like buildings, with no chat and no spam.": "Chào những người đi ngang qua và thả tim cho các tòa nhà, không chat và không spam.",
  "Nothing about your work leaves your computer: only the theme, how many floors, and whether each character is busy or idle.": "Không có gì về công việc của bạn rời khỏi máy tính: chỉ có chủ đề, số tầng, và việc mỗi nhân vật đang bận hay rảnh.",
  "See the list": "Xem danh sách",
  "Nothing is sent until you create an account. Access opens gradually, through a waitlist.": "Sẽ không có gì được gửi đi cho đến khi bạn tạo tài khoản. Quyền truy cập được mở dần, theo danh sách chờ.",
  "Create account": "Tạo tài khoản",
