  "Get close to a building's door and press E.": "Hãy lại gần cửa tòa nhà và nhấn E.",
  "Slow down: the world asked for a pause between actions.": "Chậm lại: thế giới yêu cầu nghỉ một chút giữa các hành động.",
  "Notice from Habblaud World.": "Thông báo từ Habblaud World.",
  "Minimap: click to move the camera there": "Bản đồ nhỏ: nhấp để di chuyển camera tới đó",
  "No connection to Habblaud World right now; Habblaud tries again on its own.": "Hiện không có kết nối với Habblaud World; Habblaud tự thử lại.",
  "That person isn't nearby anymore.": "Người đó không còn ở gần nữa.",
  "You stood still for a long time and left the street: walk to come back.": "Bạn đứng yên khá lâu và đã rời khỏi đường phố: hãy di chuyển để quay lại.",
  "The area is full: only the closest players show up.": "Khu vực đã đầy: chỉ hiện những người chơi ở gần nhất.",
  "You stood still for a while.": "Bạn đã đứng yên một lúc.",
  "Habblaud World is restarting: the connection drops and comes back on its own.": "Habblaud World sắp khởi động lại: kết nối sẽ ngắt rồi tự nối lại.",
  "Your account left the world: the building comes back with \"Back to the world\", in Settings.": "Tài khoản của bạn đã rời khỏi thế giới: tòa nhà trở lại với \"Quay lại thế giới\", trong Cài đặt.",
