  "Enter your building through the city and see what visitors see (nothing from your real office)": "Vào tòa nhà của bạn qua thành phố và xem những gì khách tham quan thấy (không có gì của văn phòng thật)",
  "Notify me when someone visits": "Báo khi có người ghé thăm",
