  "The building left the world: you're back on the street.": "Tòa nhà đã rời khỏi thế giới: bạn đã quay lại đường phố.",
  "Get closer to the door to go in.": "Hãy lại gần cửa hơn để vào.",
  "The building closed to visitors: you're back on the street.": "Tòa nhà đã đóng cửa với khách: bạn đã quay lại đường phố.",
  "This building is closed to visitors.": "Tòa nhà này đóng cửa với khách tham quan.",
  "You can't stay in this building anymore: you're back on the street.": "Bạn không thể ở lại tòa nhà này nữa: bạn đã quay lại đường phố.",
